+	path := filepath.Join(repo, Root, set.Policy.AnchorsRoot, "anchors.yaml")
+	var file BindingFile
+	if _, err := os.Stat(path); err == nil { if err := decodeFile(path, &file); err != nil { return err } } else if !errors.Is(err, os.ErrNotExist) { return err }
+	file.Version = 1
+	for i := range file.Anchors { if file.Anchors[i].ID == binding.ID { if !update { return fmt.Errorf("binding %q already exists (pass --update to replace it)", binding.ID) }; file.Anchors[i] = binding; return writeYAML(path, file) } }
+	file.Anchors = append(file.Anchors, binding); sort.Slice(file.Anchors, func(i,j int) bool { return file.Anchors[i].ID < file.Anchors[j].ID }); return writeYAML(path, file)
+}
+
+func validateSpec(s *Spec) error {
+	if s.Version != 1 || s.ID == "" || s.Title == "" || len(s.Requirements) == 0 { return errors.New("spec requires version 1, id, title, and requirements") }
+	reqs, accepts := map[string]bool{}, map[string]bool{}
+	for _, r := range s.Requirements { if r.ID == "" || r.Description == "" || reqs[r.ID] { return errors.New("requirements need unique ids and descriptions") }; reqs[r.ID] = true }
+	for _, a := range s.Acceptance { if a.ID == "" || a.Description == "" || !reqs[a.Requirement] || accepts[a.ID] { return errors.New("acceptance needs unique ids, descriptions, and known requirements") }; accepts[a.ID] = true }
+	for _, a := range s.Anchors { if a.ID == "" || !reqs[a.Requirement] { return errors.New("anchors need ids and known requirements") } }
+	for _, t := range s.Tests { if t.ID == "" || t.Selector.Name == "" || !accepts[t.Acceptance] { return errors.New("tests need ids, selectors, and known acceptance criteria") } }; return nil
+}
+func validateSet(set *Set) error { ids := map[string]bool{}; anchors := map[string]bool{}; for _, s := range set.Specs { if ids[s.ID] { return fmt.Errorf("duplicate specification id %q", s.ID) }; ids[s.ID]=true; for _, a := range s.Anchors { if anchors[a.ID] { return fmt.Errorf("duplicate anchor id %q",a.ID) }; anchors[a.ID]=true } }; seen := map[string]bool{}; for _, b := range set.Bindings { if !anchors[b.ID] { return fmt.Errorf("binding %q is not declared",b.ID) }; if seen[b.ID] { return fmt.Errorf("duplicate binding %q",b.ID) }; seen[b.ID]=true }; return nil }
+func decodeFile(path string, dest any) error { f,err:=os.Open(path); if err!=nil{return err}; defer f.Close(); d:=yaml.NewDecoder(io.LimitReader(f, 1<<20)); d.KnownFields(true); if err:=d.Decode(dest); err!=nil{return err}; var extra any; if err:=d.Decode(&extra); err != io.EOF { return errors.New("YAML document must contain one document") }; return nil }
+func loadYAMLFiles(root string, fn func(string) error) error { entries,err:=os.ReadDir(root); if errors.Is(err,os.ErrNotExist){return nil}; if err!=nil{return err}; var paths []string; for _,e:=range entries { if e.IsDir() || e.Type()&os.ModeSymlink != 0 { continue }; ext:=strings.ToLower(filepath.Ext(e.Name())); if ext==".yaml" || ext==".yml" { paths=append(paths,filepath.Join(root,e.Name())) } }; sort.Strings(paths); for _,p:=range paths {if err:=fn(p);err!=nil{return err}}; return nil }
+func writeYAML(path string, value any) error { if err:=os.MkdirAll(filepath.Dir(path),0o755);err!=nil{return err}; data,err:=yaml.Marshal(value);if err!=nil{return err}; return os.WriteFile(path,data,0o644) }
+func safeRelative(path string) bool { return path!="" && !filepath.IsAbs(path) && !strings.Contains(filepath.ToSlash(filepath.Clean(path)), "../") && filepath.Clean(path)!=".." }
+func rel(repo,path string) string { value,err:=filepath.Rel(repo,path);if err!=nil{return path};return filepath.ToSlash(value) }
+func digest(data []byte) string { sum:=sha256.Sum256(data);return "sha256:"+hex.EncodeToString(sum[:]) }
+func Hash(value string) string { return digest([]byte(value)) }

