+
+func runGPSCheck(ctx context.Context, opts Options, args []string) error {
+	_, flags, err := gpsFlags(args); if err != nil { return err }; repo, err := resolveRepo(ctx, opts.Env, flags.repo); if err != nil { return err }
+	set, err := intent.Load(repo); if err != nil { return err }; if len(set.Specs) == 0 { return gpsEncode(opts, flags.format, map[string]any{"schema_version":gpsSchemaVersion,"disposition":"NOT_CONFIGURED","findings":[]any{}}) }
