 	// or a trailing `...,SHA256,),`) are unparseable as calls; such lines are
 	// pure macro data, so blank them.
 	cEmptyArgMacroLinePattern = regexp.MustCompile(`^[A-Z][A-Z0-9_]*\([^()\n]*,\s*[,)][^()\n]*\)?\s*[,;]?$`)
