 		return err
 	}
 	changed, err := gitutil.ChangedFiles(ctx, repo, flags.base, "HEAD", nil)
 	if err != nil {
 		return err
 	}
 	anchors := map[string]string{}
 	for _, binding := range set.Bindings {
