+		if intentChanged && !codeChanged { findings = append(findings, map[string]any{"id":"GPS-DELTA-SPEC-ONLY","severity":"warning","subject":"intent","message":"specification changed without implementation changes"}) }
+		if codeChanged && !intentChanged { findings = append(findings, map[string]any{"id":"GPS-DELTA-CODE-ONLY","severity":"warning","subject":"code","message":"implementation changed without specification changes"}) }
 	}
