 			}
 			binding, ok := bindings[anchor.ID]
 			if !ok {
 				gaps = append(gaps, "UNBOUND_ANCHOR:"+anchor.ID)
 				continue
 			}
 			state := resolveBinding(binding, snapshot)
 			if state["state"] != "VALID" {
 				gaps = append(gaps, state["state"].(string)+":"+anchor.ID)
