 		baseline.Results = verifyResults{}
 	}
 	return baseline, nil
 }

 func verifyCountByStatus(results verifyResults) (passed, failed int) {
 	for _, status := range results {
 		if status == verifyStatusPass {
 			passed++
 			continue
 		}
 		failed++
 	}
 	return passed, failed
