 func gpsRepositoryView(ctx context.Context, repo string, head bool) map[string]string {
 	if !head {
 		return map[string]string{"kind": "working_tree"}
 	}
 	commit, tree, err := gitutil.HeadCommitAndTree(ctx, repo)
 	if err != nil {
