 			relations = append(relations, RelationRecord{
 				RecordType:    "relation",
 				FromID:        from.ID,
 				ToID:          method.ID,
 				Type:          "CALLS",
 				Confidence:    0.74,
 				Reason:        "method call resolved via chained constructor-return type",
 				RelationScope: scope,
 				Resolution:    "type_inferred",
 				TargetKind:    "symbol",
 				Evidence: []Evidence{{
