 				FromID:        from.ID,
 				ToID:          method.ID,
 				Type:          "CALLS",
 				Confidence:    0.71,
 				Reason:        "method call resolved via deep chained constructor-return type",
 				RelationScope: scope,
 				Resolution:    "type_inferred",
 				TargetKind:    "symbol",
 				Evidence: []Evidence{{
 					Kind:      "call_site",
