 	}
 	callEnd := findMatchingStaticDelimiter(call, 0, '(', ')')
 	if callEnd < 0 || strings.TrimSpace(call[callEnd+1:]) != ".pathname" {
 		return "", false
 	}
 	args := splitTopLevelStaticComma(call[1:callEnd])
 	if len(args) == 0 {
