 	for i := index; i >= 0 && index-i <= 8; i-- {
 		line := strings.TrimSpace(lines[i])
 		if line == "" {
 			continue
 		}
 		if strings.HasPrefix(line, "def ") || strings.HasPrefix(line, "async def ") {
 			continue
 		}
 		if !strings.HasPrefix(line, "@") {
 			break
 		}
