		if err != nil {
			t.Fatalf("%s: %v", tt.command, err)
		}
		lines := strings.Split(strings.TrimSpace(out.String()), "\n")
		if len(lines) < 2 {
			t.Fatalf("%s emitted too few lines:\n%s", tt.command, out.String())
